def clean_phone_numbers(apps, schema_editor):
    """
    Before phone_number becomes unique: normalize numbers to 09xxxxxxxxx,
    empty / invalid values become NULL and only the oldest account keeps a duplicated number.
    """
    from users.phone import normalize_phone

    User = apps.get_model('users', 'User')
    seen = set()
    for user in User.objects.order_by('date_joined', 'id').only('id', 'phone_number'):
        phone = normalize_phone(user.phone_number)
        if phone in seen:
            phone = None
        if phone:
            seen.add(phone)
        if phone != user.phone_number:
            User.objects.filter(pk=user.pk).update(phone_number=phone)
    User.objects.filter(email='').update(email=None)


